test("array serialization encodes special tags and distinguishes empty selections from absent state", () => {
  const hook = renderHook(() => {
    const [value, setValue] = useSearchParamState<string[]>(SearchKeys.Tags, validators.stringArray);
    return { value, setValue, search: useLocation().search };
  }, { wrapper: createRouterWrapper("/problems?keep=yes") });
  act(() => hook.result.current.setValue(["dp", "graphs & trees", "漢字"]));
  expect(hook.result.current.value).toEqual(["dp", "graphs & trees", "漢字"]);
  expect(new URLSearchParams(hook.result.current.search).get(SearchKeys.Tags)).toBe("dp,graphs & trees,漢字");
  act(() => hook.result.current.setValue([]));
  expect(hook.result.current.value).toEqual([]);
  expect(new URLSearchParams(hook.result.current.search).get(SearchKeys.Tags)).toBe("");
  act(() => hook.result.current.setValue(undefined));
  expect(new URLSearchParams(hook.result.current.search).has(SearchKeys.Tags)).toBe(false);
  expect(new URLSearchParams(hook.result.current.search).get("keep")).toBe("yes");
});

