test("Set serialization round-trips membership in insertion order", () => {
  const hook = renderHook(() => {
    const [value, setValue] = useSearchParamState<Set<string>>(SearchKeys.Tags, (input, fallback) => {
      const values = validators.stringArray(input, undefined);
      return values === undefined ? fallback : new Set(values);
    });
    return { value, setValue, search: useLocation().search };
  }, { wrapper: createRouterWrapper("/problems") });
  act(() => hook.result.current.setValue(new Set(["graphs", "dp"])));
  expect(hook.result.current.value).toEqual(new Set(["graphs", "dp"]));
  expect(new URLSearchParams(hook.result.current.search).get(SearchKeys.Tags)).toBe("graphs,dp");
});

